LOANS, CREDIT, SAVING, INVEST, SEASONAL, SAFETY = 'loans', 'credit', 'saving', 'investing', 'seasonal', 'safety'

ARTICLES = [
dict(slug='why-filipinos-borrow', cat=LOANS, kicker='Loans 101, free lesson', title='Why Filipinos borrow and how loans actually work',
 hook='Utang is not a bad word. Utang na hindi mo naiintindihan, yun ang delikado.',
 lead='Halos lahat tayo may utang at some point: tuition, motor, puhunan, hospital bill. This guide explains why people borrow, what you are really paying for, and how to tell a helpful loan from a heavy one.',
 pains=[('&#128176;', 'Sweldo is short, bills are not', 'Kulang ang sweldo sa isang buwan, kaya umuutang para lang umabot.'), ('&#127973;', 'Emergencies with no buffer', 'Biglang ospital o sira ang motor. Walang ipon, kaya utang agad.'), ('&#128722;', 'Hulugan feels easy', 'Maliit ang monthly, kaya oo agad. Hindi na tinitingnan ang kabuuan.'), ('&#129309;', 'Pakiusap sa kamag-anak', 'Nahihiya kang tumanggi kahit alam mong mabigat sa iyo.')],
 lessons=[
  ('The 4 common reasons people borrow', '<p>Most borrowing falls into four buckets. <strong>Survival</strong>: food, rent and fare when income is short. <strong>Emergency</strong>: hospital, accident, repairs. <strong>Asset</strong>: a house, a motor for work, a laptop for freelancing. <strong>Business</strong>: puhunan for stock, equipment or a bigger order.</p><p>The first two usually mean the budget or the buffer has a gap. The last two can be useful, if the thing you buy helps you earn or saves you money over time.</p>', 'Aling Nena runs a sari-sari store in Bulacan. She borrows to buy stock in bulk before Christmas because the supplier gives a lower price per case. That is a business loan with a clear plan to pay it back from sales.'),
  ('What a loan really is', '<p>A loan is simple: someone gives you money now, and you agree to pay it back later, plus a price for the time you used it. That price is <strong>interest</strong>. There may also be <strong>fees</strong>, like a processing fee or a late penalty.</p><p>Every loan has five parts you should be able to name: principal (the amount borrowed), interest rate, term (how long), payment schedule, and fees. If you cannot name all five, you are not ready to sign.</p>', None),
  ('Good debt vs heavy debt, a simple test', '<p>Ask two questions. First: <strong>will this loan help me earn or save more than it costs?</strong> Second: <strong>can I pay the monthly from my normal income without borrowing again?</strong></p><p>Two yes answers is a loan that can work for you. One no is a warning. Two no answers usually means the loan will grow into a cycle.</p>', 'Example only, not a real offer. Jun, a delivery rider in Cebu, compares two choices for a second-hand motor. Option A: borrow and pay a fixed amount monthly from his rider income, which he has tracked for 6 months. Option B: borrow for a new phone on installment because the old one is "luma na". A passes both questions. B passes neither.'),
  ('Where people borrow from', '<p>Common sources are banks, lending and financing companies, cooperatives, government programs like SSS or Pag-IBIG loans for members, credit cards, buy-now-pay-later apps, and family or friends. Each has different costs, rules and risks.</p><p>For any lending company, check that it is registered. Under RA 9474, no lending company shall conduct business unless granted an authority to operate by the SEC. Search the company name on the SEC website before you apply.</p>', None),
  ('Before you borrow, try these first', '<p>Can the need wait two weeks while you save? Can you sell something you do not use? Can you ask for a payment plan directly from the hospital, school or supplier? Sometimes the cheapest loan is the one you did not need.</p><p>If you do borrow, borrow the exact amount, for a clear purpose, with a written plan for every payment.</p>', None)],
 tool=None, play='loan-basics',
 faq=[('Is it bad to have utang?', 'Not by itself. A planned loan for an asset or business can help. The risk is borrowing for daily needs month after month, or not knowing the total cost.'), ('How do I know a lender is legit?', 'For lending and financing companies, check registration and authority to operate on the SEC website. For banks, check that it is BSP-supervised. If unsure, do not proceed.'), ('Should I borrow to lend to relatives?', 'Avoid it. You carry the full obligation even if they do not pay you back.')],
 sources=[S_LCRA]),

dict(slug='amortization-simplified', cat=LOANS, kicker='Loans 101, with calculator', title='Amortization simplified: what your monthly hulog is really paying for',
 hook='Bakit parang ang bagal bumaba ng utang kahit regular kang nagbabayad?',
 lead='Every monthly payment splits into two parts: interest and principal. Understanding that split is the fastest way to stop being surprised by a loan. May mini calculator sa baba.',
 pains=[('&#128200;', 'Balance barely moves', 'Ilang buwan ka nang nagbabayad, pero parang hindi pa rin bumababa.'), ('&#129300;', '"1.5% lang naman"', 'Mukhang maliit ang rate, pero hindi mo alam kung add-on o diminishing.'), ('&#128197;', 'Longer term, lower monthly', 'Mas maliit ang hulog, kaya kinuha mo ang mas mahabang term. Mas malaki pala ang total.')],
 lessons=[
  ('Amortization in one sentence', '<p>An amortization is a fixed regular payment that covers that month\'s interest first, and the rest goes to the principal. Early on, more of your payment goes to interest. Near the end, almost all of it goes to principal.</p>', None),
  ('A worked example, computed step by step', '<p>Here is a diminishing-balance loan, the kind where interest is computed on what you still owe.</p>', 'Example only, not a real offer. Borrow &#8369;50,000 at 1.5% per month, diminishing balance, for 12 months. The fixed payment formula is P &times; r / (1 &minus; (1 + r)<sup>&minus;n</sup>) = 50,000 &times; 0.015 / (1 &minus; 1.015<sup>&minus;12</sup>) = <strong>&#8369;4,584.00 per month</strong>. Month 1: interest = 50,000 &times; 1.5% = &#8369;750.00, principal = &#8369;3,834.00, balance &#8369;46,166.00. Month 2: interest = &#8369;692.49, principal = &#8369;3,891.51, balance &#8369;42,274.49. Month 12: interest &#8369;67.74, principal &#8369;4,516.26, balance &#8369;0. Total paid &#8369;55,008.00, total interest &#8369;5,008.00.'),
  ('Add-on vs diminishing, same number, different cost', '<p>Some loans quote an <strong>add-on</strong> or flat rate. Interest is computed on the original principal for every month, even after you have paid part of it. So the same stated rate costs more.</p>', 'Example only, not a real offer. Same &#8369;50,000, 1.5% per month, 12 months, but add-on: interest = 50,000 &times; 1.5% &times; 12 = &#8369;9,000. Monthly = 59,000 / 12 = &#8369;4,916.67. That is &#8369;3,992 more interest than the diminishing example above, for the same "1.5%".'),
  ('How to use this when you shop for a loan', '<p>Ask three things: Is the rate add-on or diminishing? What is the total amount I will pay including fees? Can I get the full schedule in writing? The Truth in Lending Act (RA 3765) requires creditors to give a clear written statement of finance charges before the transaction is completed.</p><p>Then compare loans by the total you pay, not by the monthly.</p>', None),
  ('Paying early', '<p>On a diminishing loan, extra payments toward principal reduce future interest. Some lenders charge a prepayment fee, so ask first and get the answer in writing.</p>', None)],
 tool='amort', play='loan-basics',
 faq=[('Is a longer term always worse?', 'Not always. A lower monthly can protect your budget. But the total interest is usually higher. Choose the shortest term you can comfortably pay.'), ('Why is my first payment mostly interest?', 'Because interest is computed on the full balance at the start. As the balance drops, so does the interest part.'), ('Does the calculator include fees?', 'No. It shows interest only. Add fees from your disclosure statement to get the full cost.')],
 sources=[S_TILA]),

dict(slug='loan-interest-terms-101', cat=LOANS, kicker='Pautang glossary, free lesson', title='Loan and interest terms 101: the pautang words you should know',
 hook='Hindi mo kailangang maging banker. Kailangan mo lang maintindihan ang pinipirmahan mo.',
 lead='Loan papers are full of words that sound technical. Here are the ones that matter, explained in plain Taglish, with a local example for each.',
 pains=[('&#128221;', 'Pirma lang daw', 'Pinapirma ka agad, hindi mo na nabasa ang fine print.'), ('&#128172;', 'Different words, same thing?', 'APR, EIR, add-on, flat. Nakakalito kung alin ang alin.'), ('&#128184;', 'Kulang ang natanggap', 'Inaprubahan ang buong halaga, pero mas maliit ang pumasok sa account mo.')],
 lessons=[
  ('Principal, interest, term', '<p><strong>Principal</strong> is the amount borrowed. <strong>Interest</strong> is the price of using it. <strong>Term</strong> or tenor is how long you have to pay. These three decide most of the cost.</p>', 'Si Carlo, a call center agent in Pasig, sees "&#8369;30,000, 24 months". The &#8369;30,000 is principal, 24 months is the term. He still needs the rate and the type of rate. Example only, not a real offer.'),
  ('Add-on rate vs diminishing balance', '<p><strong>Add-on</strong> (flat): interest on the original amount every month. <strong>Diminishing balance</strong>: interest on what is left. Same number, add-on costs more. See the worked example in Amortization simplified.</p>', None),
  ('Effective interest rate', '<p>The <strong>effective rate</strong> tries to show the true yearly cost after accounting for how and when you pay, and sometimes fees. It is the best single number for comparing offers. If the lender does not show it, ask for the total amount payable instead and compare that.</p>', None),
  ('Fees you might see', '<ul><li><strong>Processing or service fee</strong>: sometimes deducted from the loan, so you receive less than the principal.</li><li><strong>Documentary stamp tax</strong> and notarial fees on some loans.</li><li><strong>Late payment penalty</strong>: charged after the due date.</li><li><strong>Prepayment fee</strong>: for paying early, on some loans.</li></ul><p>Ask for each in writing. Under the Truth in Lending Act (RA 3765), creditors must give a clear written statement of the finance charges before the deal is closed.</p>', 'Example only, not a real offer. Approved &#8369;20,000 with a &#8369;1,000 processing fee deducted upfront. You receive &#8369;19,000 but repay interest on &#8369;20,000. Your real cost is higher than the stated rate.'),
  ('Collateral, co-maker, guarantor', '<p><strong>Collateral</strong> is an asset you pledge, like a car title. <strong>Co-maker</strong> is a person who signs and becomes liable if you do not pay. Being a co-maker for a friend is a real obligation. Only sign if you could pay the whole thing yourself.</p>', None),
  ('Grace period, due date, default', '<p><strong>Due date</strong> is the last day to pay. Some loans give a short <strong>grace period</strong>. <strong>Default</strong> means you failed to pay as agreed, which can trigger penalties, collection and a negative credit record.</p>', None)],
 tool=None, play='loan-basics',
 faq=[('What should I ask for before signing?', 'The written disclosure statement, the full payment schedule, and a list of all fees.'), ('Is a co-maker just a reference?', 'No. A co-maker can be required to pay. A character reference is different.'), ('What if I already signed and do not understand it?', 'Ask the lender to walk you through the schedule. Keep copies of everything you sign and pay.')],
 sources=[S_TILA]),

dict(slug='first-time-borrower-checklist', cat=LOANS, kicker='Checklist, free lesson', title='First-time borrower checklist: 10 things to do before you click Apply',
 hook='First loan mo? Ito ang checklist na sana may nagbigay sa amin dati.',
 lead='Your first loan sets your credit history. A good one builds trust with lenders. A messy one follows you. Go through this list before you apply.',
 pains=[('&#9889;', 'Approved in 5 minutes', 'Mabilis ang approval, pero hindi mo pa alam kung kaya mo ang hulog.'), ('&#128241;', 'App wants everything', 'Contacts, photos, location. Bakit kailangan?'), ('&#128556;', 'Hiya magtanong', 'Ayaw mong magmukhang walang alam, kaya hindi ka na nagtanong.')],
 lessons=[
  ('Know your number and your reason', '<p>Write down exactly what the money is for and the smallest amount that solves it. Borrowing "extra just in case" means paying interest on money you did not need.</p>', None),
  ('Do the affordability math at home', '<p>List your monthly income and essentials. Whatever is left must cover the new payment and still leave room for a small savings amount. If it only fits on paper when everything goes perfectly, it does not fit.</p>', 'Example only, not a real offer. Mae earns &#8369;22,000 take-home in Davao. Essentials are &#8369;16,000. Left: &#8369;6,000. A &#8369;5,500 monthly payment leaves only &#8369;500, too thin. A &#8369;2,500 payment leaves room to keep saving.'),
  ('Check the lender', '<p>For lending and financing companies, confirm they have SEC authority to operate (RA 9474). For banks, confirm they are BSP-supervised. Look up the exact company name, not just the app name.</p>', None),
  ('Protect your privacy', '<p>Be careful with apps that ask for access to your contact list or photos. Grant only what is needed for the loan. If an app will not work without full contact access, consider that a reason to walk away.</p>', None),
  ('Get it in writing', '<p>Ask for the disclosure statement, the full schedule and all fees before you accept. The Truth in Lending Act (RA 3765) requires written disclosure of finance charges before the deal is completed.</p>', None),
  ('Plan the payments, then set reminders', '<p>Put every due date in your phone calendar, a few days early. Pay from the same account each time and keep screenshots or receipts. If something goes wrong, contact the lender early, before the due date.</p>', None)],
 extra='<h2>The 10-point checklist</h2><ol class="checklist"><li>I know the exact purpose and amount.</li><li>The payment fits after essentials and a little savings.</li><li>I know the total amount I will pay.</li><li>I know if the rate is add-on or diminishing.</li><li>I have the list of all fees.</li><li>The lender is registered and authorized.</li><li>I did not give unnecessary phone permissions.</li><li>I have the disclosure statement and schedule.</li><li>Due dates are in my calendar.</li><li>I have a plan if income drops.</li></ol>',
 tool=None, play='borrowing-basics',
 faq=[('Does a small first loan help my credit history?', 'Paying any loan on time builds a positive record with lenders that report to the CIC. Borrow only if you actually need it.'), ('Someone asked me to pay a fee before the loan is released.', 'That is a common scam pattern. Stop and verify through the lender\'s official channels.'), ('Can I cancel after approval?', 'It depends on the lender. Ask before you accept the money.')],
 sources=[S_LCRA, S_TILA]),

dict(slug='check-your-credit-report', cat=CREDIT, kicker='Credit, free lesson', title='3 ways to check your credit report in the Philippines, and which cost money',
 hook='Bago mag-apply ng loan o card, silipin mo muna ang nakikita ng lender.',
 lead='The Credit Information Corporation (CIC) keeps a central record of borrowers\' credit data. You can request your own CIC credit report. Here are the routes CIC itself lists, what we could and could not confirm about cost, and what to do if something is wrong.',
 pains=[('&#10067;', 'Denied, no reason given', 'Na-reject ang application mo, at hindi mo alam kung bakit.'), ('&#128373;', 'Old loan you forgot', 'May lumang utang na baka naka-record pa pala.'), ('&#128203;', 'Wrong information', 'Maling pangalan, maling balance, o utang na hindi sa iyo.')],
 lessons=[
  ('What is in a CIC credit report', '<p>According to CIC, your report contains basic information like your name, TIN, SSS or GSIS numbers, address, employer and business, plus your loan contracts, utility subscriptions and other obligations CIC is authorized to collect. Lenders can access it only with your written consent and for legitimate purposes.</p>', None),
  ('Way 1: Through a CIC-accredited credit bureau app', '<p>CIC lists the <strong>Lista PH</strong> app (with CIBI Information) and the <strong>CreditMo</strong> app (with Island Credit Solutions) as ways to get your report. CIC\'s Lista PH page says it costs <strong>&#8369;199 per request</strong> (CIC page, as of Nov 4, 2026). We could not confirm CreditMo\'s price on a CIC page, so check inside the app.</p>', None),
  ('Way 2: Email CRIF Philippines', '<p>CIC also lists <strong>CRIF Philippines</strong>, another accredited bureau, where you can email a request. Fees and requirements are set by CRIF, so ask in your email. Cost: Unverified.</p>', None),
  ('Way 3: CIC Direct-to-Consumer program through authorized entities', '<p>Under CIC\'s Direct-to-Consumer (D2C) program, some banks, lenders and cooperatives can issue your CIC report, by email or walk-in. CIC says to prepare 1 to 2 valid government IDs and a "minimal service fee (depending on the AE)". Some of these entities only serve their existing borrowers, so check the CIC list first.</p>', None),
  ('So, is there a free option?', '<p>Some legal commentaries say the law entitles borrowers to one free report a year. We could not confirm that on an official CIC page as of Nov 4, 2026, so treat it as <strong>Unverified</strong>. Ask CIC or the provider directly before you pay.</p>', None),
  ('If something is wrong', '<p>CIC\'s D2C page says you can file a dispute online through CIC\'s dispute page using the transaction reference number on your report. Keep proof of payments, like receipts and certificates of full payment, to support your dispute.</p>', 'Ramon, a jeepney operator in Iloilo, finished paying a motor loan two years ago, but his report still shows a balance. He keeps the lender\'s certificate of full payment and files a dispute with the reference number from his report.')],
 tool=None, play='borrowing-basics',
 faq=[('Can I request my partner\'s report?', 'No. CIC says you cannot request another person\'s report unless you are an accredited entity with their written consent.'), ('Can I opt out of CIC?', 'CIC says no. Credit data is submitted by lenders and service providers covered by RA 9510.'), ('How often is it updated?', 'CIC says submitting entities update borrower data within 30 days of it being available to them.')],
 sources=[S_CIC_ABOUT, S_CIC_LISTA, S_CIC_D2C]),

dict(slug='how-many-credit-cards', cat=CREDIT, kicker='Credit cards, free lesson', title='How many credit cards do you really need?',
 hook='Isa? Tatlo? Lima dahil may freebie? Usapang wais tayo.',
 lead='The right number is the number you can track and pay in full. For many people that is one or two. Here is how to decide, without anyone selling you a card.',
 pains=[('&#127873;', 'Signed up for the freebie', 'Kumuha ng card dahil sa libreng luggage. Ngayon may annual fee na.'), ('&#128197;', 'Too many due dates', 'Iba-iba ang due date, kaya may nakakalimutan.'), ('&#128260;', 'Card to pay card', 'Ginagamit ang isang card pambayad sa isa pa.'), ('&#128202;', 'Limit feels like income', 'Malaki ang total limit, kaya parang may pera ka kahit wala.')],
 lessons=[
  ('Start from the job, not the card', '<p>List what you actually need a card for: online purchases, a backup for emergencies, a separate card for business expenses, travel. Each card should have one job. If you cannot name the job, you do not need the card.</p>', None),
  ('The one-card setup', '<p>For most first-time cardholders, one card is enough. Use it for planned spending you already budgeted, and pay the full statement balance every due date. That builds history without stress.</p>', 'Joy, a teacher in Batangas, uses one card for groceries and bills she already pays monthly. She pays the full statement on payday. One due date, one app, no surprises.'),
  ('When two cards make sense', '<p>A second card can help if you run a small business and want business expenses separate, or as a backup in case one card is blocked or lost. Keep it in a different wallet or app.</p>', None),
  ('The hidden cost of more cards', '<p>More cards means more annual fees, more due dates, more apps to secure and more chances to miss a payment. A missed payment can mean interest and late fees. For how card interest and the float work, see our guide on using a credit card for business.</p>', None),
  ('A simple self-check', '<p>You are ready for another card only if: you paid every current card in full for the last 6 months, you track every card\'s due date, and you have a specific job for the new one.</p>', None)],
 tool=None, play='financial-fitness',
 faq=[('Does closing a card hurt me?', 'Rules vary by lender. Pay off the balance first, ask the bank for written confirmation of closure, and keep it.'), ('Is a card with no annual fee always better?', 'Not always, but fees should be weighed against what you actually use. Read the bank\'s current fee table.'), ('Should I get a card to build credit?', 'Only if you can pay in full monthly. Paying any loan on time also builds a record.')],
 sources=[]),

dict(slug='rule-50-30-20', cat=SAVING, kicker='Budgeting, with calculator', title='The 50-30-20 rule for Filipino salaries, made realistic',
 hook='50% needs, 30% wants, 20% ipon. Pero paano kung Metro Manila rent pa lang, kalahati na?',
 lead='50-30-20 is a starting point, not a law. Here is how to use it on a Philippine salary, adjust it honestly, and still save something every payday.',
 pains=[('&#127968;', 'Rent eats everything', 'Upa at kuryente pa lang, ubos na ang kalahati.'), ('&#128106;', 'Family support', 'May padala sa probinsya na hindi kasama sa mga budget template.'), ('&#9749;', 'Small wants add up', 'Milk tea, delivery, Shopee cart. Maliit pero araw-araw.')],
 lessons=[
  ('What the three buckets mean', '<p><strong>Needs (50%)</strong>: rent, food, utilities, transport, minimum loan payments, family support you are committed to. <strong>Wants (30%)</strong>: eating out, shopping, subscriptions, gimik. <strong>Savings and debt (20%)</strong>: emergency fund, goals, extra payments to clear debt faster.</p>', 'Example only, not a real offer. Take-home pay &#8369;25,000 a month: needs &#8369;12,500, wants &#8369;7,500, savings and debt &#8369;5,000.'),
  ('Use take-home pay, not gross', '<p>Your payslip deductions like tax, SSS, PhilHealth and Pag-IBIG are already gone before money reaches you. Budget from what actually lands in your account.</p>', None),
  ('When needs are more than 50%', '<p>That is common, especially in cities. Try 60-20-20 or even 70-20-10 for now. The important part is that the savings bucket is never zero. Then work on the biggest need, like moving closer to work or sharing rent, over time.</p>', 'Example only. Bea in Quezon City takes home &#8369;25,000, and needs are &#8369;16,000, more than half. She uses 64-26-10: wants &#8369;6,500, savings &#8369;2,500. Once her motor loan is paid, she moves to 54-26-20.'),
  ('Where family support goes', '<p>If padala is fixed and expected, put it in needs. If it is extra and flexible, put it in wants. Being honest about this keeps the budget from breaking every month.</p>', None),
  ('Make it automatic', '<p>On payday, move the savings bucket first to a separate account. What you do not see, you will not spend. For where to keep it, see our guide on bank vs digital bank vs e-wallet.</p>', None)],
 tool='budget', play='financial-fitness',
 faq=[('What if I am paid weekly or daily?', 'Apply the same split to each payout, or to your average monthly income.'), ('Should debt payments be in needs or savings?', 'Minimum payments go in needs. Extra payments to clear debt faster go in the 20%.'), ('Is 20% too ambitious?', 'Start with any amount, even 5%. The habit matters more than the number at first.')],
 sources=[]),

dict(slug='petsa-de-peligro-survival', cat=SAVING, kicker='Budgeting, free lesson', title='Petsa de Peligro survival tips: making it to the next sahod',
 hook='Kinsenas at katapusan lang masaya? Hindi dapat ganyan.',
 lead='Petsa de peligro, those tight days before payday, is mostly a timing problem. These tips focus on the timing, not on cutting your joy to zero.',
 pains=[('&#128546;', 'Day 10 and broke', 'Sahod noong 30, wala na pagdating ng 10.'), ('&#127836;', 'Instant noodles week', 'Ang huling linggo ay noodles at de-lata.'), ('&#128184;', 'Utang sa kaibigan', 'Laging may hinihiraman bago sumweldo.')],
 lessons=[
  ('Split the payday into "mini paydays"', '<p>Instead of spending freely after sahod, divide your spending money into weekly envelopes or separate e-wallet pockets. You give yourself an allowance every Monday. When this week\'s envelope is empty, you wait for Monday.</p>', 'Example only. Paolo takes home &#8369;14,000 every kinsenas. After bills and savings, &#8369;5,000 is for daily spending. He moves &#8369;2,500 to a "Week 1" pocket and &#8369;2,500 to "Week 2".'),
  ('Pay bills on payday, not on due date', '<p>The money for bills disappears if it sits in your main account. Pay or set aside bill money the day you get paid.</p>', None),
  ('Plan meals for the last week first', '<p>Buy rice, eggs, canned goods and vegetables for the tight week right after payday. Then the last week is already covered.</p>', None),
  ('Watch the "maliit lang" leaks', '<p>Check one week of e-wallet and bank history. Count delivery fees, small online orders and convenience store runs. Pick one to reduce, not all.</p>', None),
  ('Build a tiny buffer', '<p>Your goal: one extra week of spending money sitting in savings. Once you have it, petsa de peligro becomes "petsa ng konting ingat" instead.</p>', None)],
 tool=None, play='financial-fitness',
 faq=[('Should I use a credit card to survive the last week?', 'Only if you can pay the full statement from the next payday. Otherwise it moves the problem to next month with interest.'), ('What about salary loans?', 'They can help in emergencies, but repeated salary loans for daily needs usually mean the budget needs fixing.'), ('My income is irregular.', 'Use your lowest typical month as your planning number, and save extra in good months.')],
 sources=[]),

dict(slug='emergency-fund-how-much', cat=SAVING, kicker='Savings, with calculator', title='Rainy day emergency fund: how much is enough?',
 hook='Hindi mo kailangan ng milyon. Kailangan mo ng target na totoo para sa buhay mo.',
 lead='An emergency fund is money set aside for the unplanned: job loss, illness, typhoon repairs. Here is how to find your number and reach it step by step.',
 pains=[('&#9928;', 'Bagyo season', 'Sira ang bubong, baha ang appliance, wala kang pondo.'), ('&#127973;', 'Sudden hospital bill', 'Kailangan ng cash agad, kaya utang.'), ('&#128188;', 'Lost job or slow month', 'Walang kita ng ilang linggo, walang sandalan.')],
 lessons=[
  ('Count essentials, not your whole spending', '<p>Add up one month of true essentials: rent, food, utilities, transport, minimum debt payments, medicines and committed family support. That is your monthly essentials number.</p>', None),
  ('Choose your months', '<p>A common starting guide is 3 months of essentials for stable salaried work, and closer to 6 months if your income is irregular, you are the only earner, or you have dependents. These are guidelines, not rules. For daily earners, see our guide on building a fund on daily income.</p>', 'Example only. Monthly essentials &#8369;18,000. Three months: &#8369;54,000. Six months: &#8369;108,000.'),
  ('Break it into rungs', '<p>A big target can feel impossible. Start with one week of essentials, then one month, then three. Celebrate each rung.</p>', None),
  ('Where to keep it', '<p>Keep it separate from spending money, easy to withdraw, and in an account insured by PDIC where applicable. See our guides on bank vs digital bank vs e-wallet and where to park idle money for current rates and the rules we checked.</p>', None),
  ('What counts as an emergency', '<p>Unplanned, necessary and urgent. A sale on a phone is not. If you use the fund, refilling it becomes the next savings goal.</p>', None)],
 tool='efund', play='financial-fitness',
 faq=[('Should I pay debt or build the fund first?', 'Many people build a small starter fund first, then focus on high-interest debt, then grow the fund.'), ('Can I keep it in an e-wallet?', 'An e-wallet balance is not a bank deposit. Savings products inside some apps are bank accounts. Read our bank vs e-wallet guide.'), ('Is cash at home OK?', 'A small amount for typhoon days is practical. Keep most of it in an account so it is safer.')],
 sources=[]),

dict(slug='ipon-challenges-2027', cat=SAVING, kicker='Savings, with generator', title='Ipon challenges for 2027: pick one, print it, start in January',
 hook='Bagong taon, bagong ipon. Pero yung kaya mong tapusin.',
 lead='An ipon challenge turns saving into a weekly habit. Below are three styles and a generator that builds your 2027 schedule by week. Choose the one that fits your income, not the one that looks impressive online.',
 pains=[('&#128163;', 'Quit by March', 'Excited sa January, sumuko na pagdating ng Marso.'), ('&#128200;', 'Last weeks too heavy', 'Ang huling linggo ng 52-week, ang laki na ng kailangan.'), ('&#129512;', 'Coin jar opened', 'Nabuksan ang alkansya para sa "emergency" na hindi naman.')],
 lessons=[
  ('The classic 52-week, ascending', '<p>Week 1 you save 1 unit, week 2 saves 2 units, up to week 52. It starts easy and gets heavier near December, which is also when expenses spike.</p>', 'Example only. Unit &#8369;20: week 1 &#8369;20, week 52 &#8369;1,040. Total after 52 weeks: 20 &times; (1 + 2 + ... + 52) = 20 &times; 1,378 = &#8369;27,560.'),
  ('Reverse 52-week, descending', '<p>Start with the biggest week in January, when 13th month and bonuses may still be around, and end with the smallest in December. Same total, easier finish.</p>', None),
  ('Flat weekly', '<p>The same amount every week. Simple and predictable, good for fixed salaries.</p>', 'Example only. &#8369;300 a week for 52 weeks = &#8369;15,600.'),
  ('Make it stick', '<p>Use a separate savings account or pocket, not a coin jar you can easily open. Set a weekly reminder on the same day as payday. If you miss a week, double the next one or simply continue. Done is better than perfect.</p>', None),
  ('Give the money a job', '<p>Name the goal before you start: emergency fund, tuition, a new laptop for work. A named goal is easier to protect.</p>', None)],
 tool='ipon', play='financial-fitness',
 faq=[('When does the generator start?', 'On Monday, January 4, 2027, the first Monday of the year. Each row is the week starting that date.'), ('Can I do bi-weekly?', 'Yes. Set weeks to 26 and use your payday as the start.'), ('Is my schedule saved?', 'No. Everything is computed in your browser. Print or screenshot it.')],
 sources=[]),

dict(slug='thirteenth-month-pay-plan', cat=SEASONAL, kicker='Seasonal, with calculator', title='13th month pay plan: before it arrives, decide where it goes',
 hook='Dumating ang 13th month, nawala sa Noche Buena at sale. Sound familiar?',
 lead='The 13th month pay is a legal benefit for many private-sector rank-and-file employees. Here is how it is computed, when it is due, and a simple plan to make it last past January.',
 pains=[('&#127876;', 'Gone by December 26', 'Regalo, handa, sale. Pagdating ng Enero, wala nang natira.'), ('&#128179;', 'Card bills in January', 'Ang mga swipe noong Disyembre, babayaran pala sa Enero.'), ('&#10067;', 'Not sure how much', 'Hindi mo alam kung tama ang natanggap mo.')],
 lessons=[
  ('The rules, briefly', '<p>Memorandum Order No. 28 (1986) requires employers to pay rank-and-file employees a 13th month pay not later than December 24 every year. The PD 851 implementing rules define it as one-twelfth (1/12) of the basic salary earned within the calendar year. Allowances and benefits not part of basic salary are generally not included. Rules have details and exceptions, so check DOLE\'s current guidance for your situation.</p>', None),
  ('Compute your estimate', '<p>Add up the basic salary you earned this calendar year and divide by 12. If you joined mid-year, use only the months you worked.</p>', 'Example only. Basic salary &#8369;20,000 a month, worked all 12 months: 20,000 &times; 12 / 12 = &#8369;20,000. Worked 7 months: 20,000 &times; 7 / 12 = &#8369;11,666.67.'),
  ('The tax part', '<p>Under the TRAIN law (RA 10963), 13th month pay and other benefits are exempt from income tax up to a combined &#8369;90,000 per year (sourced, see below). Amounts above that are taxable.</p>', None),
  ('A simple split before it lands', '<p>Decide the split before payday so it does not disappear. One option: clear upcoming debts first, top up your emergency fund, set aside January expenses like tuition or renewals, then enjoy the rest guilt-free.</p>', 'Example only. &#8369;20,000: &#8369;6,000 to pay off a card balance, &#8369;6,000 to emergency fund, &#8369;4,000 reserved for January bills, &#8369;4,000 for Christmas.'),
  ('January is part of the plan', '<p>Many people forget that December card swipes become January bills. Set aside that amount now.</p>', None)],
 tool='13th', play='financial-fitness',
 faq=[('I am a freelancer or commission-based. Do I get it?', 'Coverage depends on the type of work and pay. Some exclusions exist in the rules. Check DOLE guidance or ask your employer or HR.'), ('Can it be paid in two parts?', 'Some employers split it. The deadline for the full amount is December 24.'), ('Is the calculator exact?', 'It is an estimate of the minimum. Your employer may pay more.')],
 sources=[S_MO28, S_PD851, S_TRAIN]),

dict(slug='online-scams-to-avoid', cat=SAFETY, kicker='Safety, free lesson', title='12 online scams to avoid, and what to do if you are targeted',
 hook='Hindi ka tanga kapag na-scam. Magaling lang talaga sila mag-panggap. Kaya alamin natin ang galaw nila.',
 lead='Scammers use the same handful of tricks in new costumes. Learn the patterns, verify through official channels, and report. Sources from BSP, SEC and the CICC are listed below.',
 pains=[('&#128241;', '"Your account is locked"', 'May text na may link, mukhang galing sa bangko mo.'), ('&#128222;', 'Caller asks for OTP', 'May tumawag, kilala ang pangalan mo, humihingi ng code.'), ('&#128176;', 'Sigurado raw ang tubo', 'May nag-alok ng investment na sigurado raw ang kita.'), ('&#128230;', 'Pay first, then receive', 'Bayad muna bago ma-release ang loan, parcel o premyo.')],
 lessons=[
  ('The 12 to know', '<ol><li><strong>Phishing emails</strong> with links to fake login pages.</li><li><strong>Smishing</strong>: the same trick by text message.</li><li><strong>Vishing</strong>: calls pretending to be your bank or a popular company.</li><li><strong>OTP requests</strong> from anyone, by text, chat or call.</li><li><strong>Fake bank or e-wallet pages</strong> on social media offering "help".</li><li><strong>Investment schemes</strong> promising sure-win or very high short-term returns.</li><li><strong>Unregistered online lenders</strong> and pay-first loan "release fees".</li><li><strong>Task or job scams</strong>: pay to unlock tasks or commissions.</li><li><strong>Love or friendship scams</strong> that end with a money request.</li><li><strong>Fake online sellers</strong> asking for payment outside the platform.</li><li><strong>Fake delivery or parcel fees</strong> by text link.</li><li><strong>Account takeover</strong>: hacked social accounts asking friends for money.</li></ol>', None),
  ('Rule 1: banks do not ask for your secrets', '<p>BSP\'s consumer guide says banks and financial institutions will not ask for personal information, account details or passwords by email, and that you should call your bank directly to verify. Treat any request for OTP, PIN or password as a red flag, whoever it claims to be.</p>', 'Lito in Pampanga gets a call: "Sir, from your bank po, may suspicious transaction, paki-read ng code." He hangs up, opens his banking app himself, and calls the number printed on his card.'),
  ('Rule 2: be careful with links', '<p>Under the AFASA rules in BSP\'s booklet, banks and supervised institutions must not send clickable links or QR codes by email, messaging apps or SMS, except in limited cases, for example when you started the action or the link only gives information. Open the official app or type the address yourself.</p>', None),
  ('Rule 3: "sure-win returns" is the warning', '<p>The SEC regularly issues advisories against entities that solicit investments from the public without authority, often with promises of high or "sure" returns. Check the SEC website for advisories and registration before you put in any money.</p>', None),
  ('If you are targeted or lost money', '<p>Act fast. Call your bank or e-wallet through its official hotline to block or report. Then report to the Inter-Agency Response Center hotline <strong>1326</strong>, operated by DICT, CICC, NPC and NTC with PNP and NBI as enforcement arms. Keep screenshots, numbers, and reference numbers.</p>', None)],
 tool=None, play='borrowing-basics',
 faq=[('The text has my full name. Is it real?', 'Not necessarily. Scammers can get names from leaks or social media. Verify through the official app or hotline.'), ('I clicked a link but did not type anything.', 'Close it, do not enter anything, and watch your accounts. If you entered details, call your bank right away.'), ('Can I get my money back?', 'Sometimes, depending on the case and how fast you report. Report to your bank and to 1326 as soon as possible.')],
 sources=[S_BSP_FRAUD, S_AFASA, S_SEC_ADV, S_1326, S_1326B]),
]

